<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>کاربران</title><style>body{font-family:Tahoma;background:#07111f;color:#e9f3fb;padding:30px}.panel{background:#0a1b2b;border:1px solid #1b354b;border-radius:16px;padding:20px;max-width:1200px;margin:auto}a,button{color:#6ee7d0}.btn{padding:7px 10px;background:#10283c;border:0;border-radius:8px;text-decoration:none;margin:2px}table{width:100%;border-collapse:collapse}td,th{padding:11px;border-bottom:1px solid #173047;text-align:right}form{display:inline}.danger{background:#4a1f2a;border:0;padding:8px;border-radius:8px}</style><div class="panel"><h1>کاربران و دسترسی کاربران</h1><p><a class="btn" href="{{ route('users.create') }}">کاربر جدید</a> <a class="btn" href="{{ route('roles.index') }}">مدیریت نقش‌ها</a> <a class="btn" href="{{ route('personnel.index') }}">پرسنل</a></p>@if(session('success'))<p>{{ session('success') }}</p>@endif<table><tr><th>نام</th><th>ایمیل</th><th>نقش</th><th>وضعیت</th><th>عملیات</th></tr>@foreach($users as $u)<tr><td>{{ $u->name }} @if($u->isAccountOwner()) (مالک حساب) @endif</td><td>{{ $u->email }}</td><td>{{ $u->roles->pluck('name')->join('، ') ?: 'بدون نقش' }}</td><td>{{ $u->is_active && $u->pivot->is_active ? 'فعال' : 'غیرفعال' }}</td><td>@if(!$u->isAccountOwner())<a class="btn" href="{{ route('users.edit',$u) }}">ویرایش</a><a class="btn" href="{{ route('users.access',$u) }}">دسترسی</a>@if($u->is_active)<form method="POST" action="{{ route('users.deactivate',$u) }}">@csrf<button class="danger">غیرفعال</button></form>@else<form method="POST" action="{{ route('users.activate',$u) }}">@csrf<button class="btn">فعال</button></form>@endif @endif</td></tr>@endforeach</table>{{ $users->links() }}</div></html>